
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_ktbm_0_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_ktbm_0", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.783281677801102e+00, -4.689676995079151e+00, -4.558539547724170e+00, -4.376926806877679e+00, -4.129524187892017e+00, -3.800292533735297e+00, -3.376229500991424e+00, -2.853300239340459e+00, -2.241290177886586e+00, -1.570231629587429e+00, -9.692411208395253e-01, -6.735528280253902e-01, -6.184449509184439e-01, -5.253117076044023e-01, -3.709509247034603e-01, -2.150782347283161e-01, -9.718381446719321e-02, -3.231916286647189e-02, -6.933507266565728e-03, -7.796086166297454e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


